/// @sort 32
uniform float A = 1.0;
/// @sort 32
uniform float3 V = float3(1.0, 2.0, 3.0);
// `True` / `FALSE`, `vec3`, `mix` / `fract` / `mod`: read the 1.x way, written the 2.0 way where the front end owns the spelling.
/// @name M_LpGSpellings
export void M_LpGSpellings(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float3 Mixed = mix(V, float3(1.0, 1.0, 1.0), 0.25);
    Color = fract(Mixed) + mod(Mixed, 0.5);
    Base.EmissiveColor = Color;
}
